# Byte-order check of the cspot core (Shannon, Utils, nanopb, Tremor): builds harness.cpp for x86 (little-endian) and
# powerpc64 (big-endian, static, run under qemu-ppc64) and compares what they print.  See docs/music-services-notes.md.
#
#   CSPOT_DIR        the cspot library directory of a cspot checkout (its src/, include/, bell/)     [~/sp/cspot/cspot]
#   CSPOT_BUILD_DIR  a CMake build of cspotcli there, whose protobuf/*.pb.[ch] are generated by nanopb     [~/sp/build-host/targets/cli/cspot]
#   WORK_DIR         where the objects and outputs go                                                [/tmp/spotify_be]
# Needs ffmpeg with libvorbis (for the test file), powerpc64-linux-gnu-gcc/g++ and qemu-ppc64.
HERE=$(cd "$(dirname "$0")" && pwd)
C=${CSPOT_DIR:-/home/ethan/sp/cspot/cspot}
B=${CSPOT_BUILD_DIR:-/home/ethan/sp/build-host/targets/cli/cspot}
NP=$C/bell/external/nanopb
TR=$C/bell/external/tremor
W=${WORK_DIR:-/tmp/spotify_be}
mkdir -p $W && cd $W || exit 1
[ -f test.ogg ] || ffmpeg -v error -y -f lavfi -i "sine=frequency=440:duration=2:sample_rate=44100" -f lavfi -i "sine=frequency=660:duration=2:sample_rate=44100" \
   -filter_complex "[0][1]amerge=inputs=2,volume=0.5" -c:a libvorbis -q:a 4 test.ogg
INC="-I$C/include -I$C/bell/main/utilities/include -I$NP -I$B -I$C -I$TR"
DEF="-DPB_ENABLE_MALLOC -DPB_FIELD_32BIT"
CSRC="$NP/pb_common.c $NP/pb_encode.c $NP/pb_decode.c $B/protobuf/keyexchange.pb.c $B/protobuf/mercury.pb.c"
TRSRC=$(ls $TR/*.c | grep -v example)
CXXSRC="$HERE/harness.cpp $C/src/Shannon.cpp $C/src/Utils.cpp $C/bell/main/utilities/NanoPBHelper.cpp"
build() {  # $1 prefix, then extra flags
  P=$1; shift
  rm -rf obj-$P; mkdir obj-$P
  for f in $CSRC $TRSRC; do ${P}gcc -O2 -w $DEF $INC "$@" -c -o obj-$P/$(basename $f .c).o $f || return 1; done
  for f in $CXXSRC; do ${P}g++ -std=gnu++17 -O2 -w $DEF $INC "$@" -c -o obj-$P/$(basename $f .cpp).o $f || return 1; done
  ${P}g++ "$@" -o harness-$P obj-$P/*.o || return 1
}
build "" || { echo "LE build failed"; exit 1; }
build powerpc64-linux-gnu- -static || { echo "BE build failed"; exit 1; }
./harness- test.ogg > out-le.txt 2>&1 || echo "LE run exit $?"
qemu-ppc64 ./harness-powerpc64-linux-gnu- test.ogg > out-be.txt 2>&1 || echo "BE run exit $?"
echo "--- little-endian"; cat out-le.txt
echo "--- big-endian"; cat out-be.txt
# The one line that must differ is hton64: host-to-network order is a swap on x86 and the identity on the PS3.
if diff <(grep -v '^hton64' out-le.txt) <(grep -v '^hton64' out-be.txt) > /dev/null; then echo "IDENTICAL: every line but hton64 (which differs by design) matches"; else echo "DIFFER:"; diff out-le.txt out-be.txt; exit 1; fi
